BEGIN;
CREATE TABLE payer(payer_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, payer_type text NOT NULL CHECK(payer_type IN ('INDIVIDUAL','BUSINESS')), full_name text NOT NULL, tin text NOT NULL UNIQUE, phone text, email text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE revenue_type(revenue_code text PRIMARY KEY, name text NOT NULL, category text NOT NULL CHECK(category IN ('TAX','WATER')), gl_code text NOT NULL, is_active boolean NOT NULL DEFAULT true);
CREATE TABLE water_account(account_no text PRIMARY KEY, payer_id bigint NOT NULL REFERENCES payer, meter_no text NOT NULL UNIQUE, tariff_class text NOT NULL CHECK(tariff_class IN ('DOMESTIC','COMMERCIAL','INSTITUTIONAL')), status text NOT NULL, UNIQUE(account_no,payer_id));
CREATE TABLE meter_reading(reading_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, meter_no text NOT NULL REFERENCES water_account(meter_no), reading_date date NOT NULL, reading_value numeric(12,3) NOT NULL CHECK(reading_value>=0), reading_type text NOT NULL CHECK(reading_type IN ('ACTUAL','ESTIMATED')), UNIQUE(meter_no,reading_date));
CREATE TABLE assessment(assessment_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, payer_id bigint NOT NULL REFERENCES payer, revenue_code text NOT NULL REFERENCES revenue_type, amount_due numeric(18,2) NOT NULL CHECK(amount_due>0), due_date date NOT NULL, status text NOT NULL DEFAULT 'OPEN' CHECK(status IN ('OPEN','PART_PAID','PAID')), penalty_amount numeric(18,2) NOT NULL DEFAULT 0 CHECK(penalty_amount>=0 AND penalty_amount<=amount_due), account_no text, billing_period date, FOREIGN KEY(account_no,payer_id) REFERENCES water_account(account_no,payer_id), CHECK((account_no IS NULL AND billing_period IS NULL) OR (account_no IS NOT NULL AND billing_period IS NOT NULL)), UNIQUE(assessment_id,payer_id,revenue_code));
CREATE TABLE fmis_batch(batch_id uuid PRIMARY KEY, business_date date NOT NULL, currency text NOT NULL, status text NOT NULL CHECK(status IN ('PENDING','POSTED','FAILED')), reference text, attempts int NOT NULL DEFAULT 0 CHECK(attempts BETWEEN 0 AND 3), error text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE payment(payment_id uuid PRIMARY KEY, payer_id bigint NOT NULL REFERENCES payer, assessment_id bigint, revenue_code text NOT NULL REFERENCES revenue_type, amount numeric(18,2) NOT NULL CHECK(amount>0), currency text NOT NULL CHECK(currency='USD'), channel text NOT NULL CHECK(channel IN ('BANK','MOBILE_MONEY','CASH')), external_ref text NOT NULL UNIQUE CHECK(length(trim(external_ref)) BETWEEN 1 AND 100), paid_at timestamptz NOT NULL, fmis_status text NOT NULL DEFAULT 'PENDING' CHECK(fmis_status IN ('PENDING','POSTED','FAILED')), batch_id uuid REFERENCES fmis_batch, FOREIGN KEY(assessment_id,payer_id,revenue_code) REFERENCES assessment(assessment_id,payer_id,revenue_code));
CREATE INDEX ix_payment_period_revenue ON payment(paid_at,revenue_code) INCLUDE(amount,currency);
CREATE INDEX ix_payment_assessment ON payment(assessment_id) INCLUDE(amount);
CREATE INDEX ix_payment_fmis ON payment(paid_at) WHERE batch_id IS NULL;
CREATE INDEX ix_assessment_overdue ON assessment(due_date) WHERE status<>'PAID';
CREATE TABLE failed_payment(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, payload jsonb NOT NULL, reasons text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE idempotency_record(key text PRIMARY KEY, body_hash text NOT NULL, response jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE callback_replay(signature text PRIMARY KEY, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE report_version(id int PRIMARY KEY CHECK(id=1), version bigint NOT NULL);
INSERT INTO report_version VALUES(1,0);
CREATE FUNCTION invalidate_reports() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN UPDATE report_version SET version=version+1 WHERE id=1; RETURN NEW; END $$;
CREATE TRIGGER payment_report_version AFTER INSERT ON payment FOR EACH STATEMENT EXECUTE FUNCTION invalidate_reports();
CREATE TABLE fmis_batch_line(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, batch_id uuid NOT NULL REFERENCES fmis_batch, gl_code text NOT NULL, debit numeric(18,2) NOT NULL CHECK(debit>=0), credit numeric(18,2) NOT NULL CHECK(credit>=0), CHECK((debit>0 AND credit=0) OR (credit>0 AND debit=0)));
CREATE TABLE mock_fmis_journal(batch_id uuid PRIMARY KEY, body_hash text NOT NULL, reference text NOT NULL UNIQUE, journal jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
COMMIT;
